CREATE OR REPLACE FUNCTION calculate_cpi(p_artref character)
RETURNS numeric AS $$
DECLARE
    v_histsignrating smallint;
    v_researchvalrating integer;
    v_cultscore smallint;
    v_conservestatus character varying;
    v_conserve_status_num integer;
    v_cpi numeric;
BEGIN
    -- Get ratings from artifactratings table
    SELECT ar.histsignrating, ar.researchvalrating, ar.cultscore, a.conservestatus
    INTO v_histsignrating, v_researchvalrating, v_cultscore, v_conservestatus
    FROM artifactscore a
    JOIN artifactratings ar ON a.artregistry = ar.artref
    WHERE a.artregistry = p_artref;

    -- Map conservestatus to numeric value
    CASE v_conservestatus
        WHEN 'Excellent' THEN v_conserve_status_num := 1;
        WHEN 'Good' THEN v_conserve_status_num := 3;
        WHEN 'Fair' THEN v_conserve_status_num := 5;
        WHEN 'Poor' THEN v_conserve_status_num := 7;
        WHEN 'Critical' THEN v_conserve_status_num := 10;
        ELSE v_conserve_status_num := 0;
    END CASE;

    -- Calculate CPI
    v_cpi := (v_histsignrating + v_researchvalrating + v_cultscore) * (10 - v_conserve_status_num) / 30.0;

    RETURN v_cpi;
END;
$$ LANGUAGE plpgsql;

